<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'api');$flash='';$ft='ok';$newToken='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$act=(string)($_POST['action']??'');try{if($act==='create'){$q=$pdo->prepare('SELECT COUNT(*) FROM reseller_api_keys WHERE reseller_id=? AND revoked_at IS NULL AND expires_at>?');$q->execute([$ctx['id'],time()]);if((int)$q->fetchColumn()>=5)throw new DomainException('حداکثر پنج کلید فعال مجاز است.');$name=mb_substr(trim((string)($_POST['name']??'')),0,100);if($name==='')throw new DomainException('نام کلید لازم است.');$days=max(1,min(90,(int)($_POST['days']??30)));$allowed=['stats','customers','invoices'];if(rxp_can($ctx,'broadcast'))$allowed[]='message_write';if(rxp_can($ctx,'extend_user'))$allowed[]='service_write';if(rxp_can($ctx,'products'))$allowed[]='product_write';$allowed[]='settlement_write';$perms=[];foreach($allowed as$p)if(isset($_POST['perm_'.$p]))$perms[]=$p;if(!$perms)throw new DomainException('حداقل یک دسترسی انتخاب کنید.');$ips=array_values(array_filter(array_map('trim',preg_split('/[,\s]+/',(string)($_POST['ip_allowlist']??'')))));if(count($ips)>10)throw new DomainException('حداکثر ۱۰ IP مجاز است.');foreach($ips as$ip)if(!filter_var($ip,FILTER_VALIDATE_IP))throw new DomainException('IP Allowlist نامعتبر است.');$newToken='rf_r_'.bin2hex(random_bytes(32));$hash=hash('sha256',$newToken);$pdo->prepare('INSERT INTO reseller_api_keys(reseller_id,name,key_prefix,key_hash,permissions,ip_allowlist,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$ctx['id'],$name,substr($newToken,0,16),$hash,json_encode($perms),json_encode($ips),time()+$days*86400,time()]);rxp_audit($pdo,$ctx,'api_key.create',$name,$perms);$flash='کلید ساخته شد؛ فقط همین بار نمایش داده می‌شود.';}elseif($act==='revoke'){$id=(int)($_POST['id']??0);$pdo->prepare('UPDATE reseller_api_keys SET revoked_at=? WHERE id=? AND reseller_id=? AND revoked_at IS NULL')->execute([time(),$id,$ctx['id']]);rxp_audit($pdo,$ctx,'api_key.revoke',(string)$id);$flash='کلید لغو شد.';}}catch(Throwable$e){$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}
try{$q=$pdo->prepare('SELECT * FROM reseller_api_keys WHERE reseller_id=? ORDER BY id DESC');$q->execute([$ctx['id']]);$keys=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$keys=[];$flash='Migration 004 اجرا نشده است.';$ft='err';}rxp_layout_start($ctx,'کلیدهای API','api_keys.php');rxp_flash($flash,$ft);?>
<h1 class="rxp-title">رابط برنامه‌نویسی نماینده</h1><div class="rxp-sub">ساخت و لغو کلیدهای امن برای اتصال نرم‌افزارهای شما به داده‌های مجاز پنل نمایندگی.</div><?php if($newToken!==''):?><div class="rxp-card"><h2>توکن جدید</h2><textarea readonly style="width:100%;direction:ltr"><?=rxp_h($newToken)?></textarea><p class="rxp-flash err">پس از خروج از این صفحه دیگر قابل بازیابی نیست.</p></div><?php endif;?><div class="rxp-card"><h2>ساخت کلید</h2><form method="post" class="rxp-form"><input type="hidden" name="action" value="create"><div class="rxp-field"><label>نام</label><input name="name" required></div><div class="rxp-field"><label>اعتبار روز؛ حداکثر ۹۰</label><input type="number" name="days" min="1" max="90" value="30"></div><div class="rxp-field"><label>IP Allowlist اختیاری؛ جدا با کاما</label><input name="ip_allowlist" placeholder="203.0.113.10, 2001:db8::1"></div><?php $apiDefs=['stats'=>'آمار','customers'=>'مشتریان','invoices'=>'سفارش‌ها'];if(rxp_can($ctx,'broadcast'))$apiDefs['message_write']='ارسال پیام مستقیم';if(rxp_can($ctx,'extend_user'))$apiDefs['service_write']='عملیات سرویس';if(rxp_can($ctx,'products'))$apiDefs['product_write']='ساخت محصول';$apiDefs['settlement_write']='درخواست تسویه';foreach($apiDefs as$p=>$l):?><label class="rxp-muted"><input type="checkbox" name="perm_<?=$p?>" checked> <?=$l?></label><?php endforeach;?><button class="rxp-btn">ساخت</button></form><p class="rxp-muted">GET فقط Bearer می‌خواهد. POST علاوه بر Bearer به <code>X-RF-Timestamp</code>، <code>X-RF-Nonce</code>، <code>X-RF-Signature</code> و <code>Idempotency-Key</code> نیاز دارد. امضا: HMAC-SHA256 روی timestamp، nonce، POST، path و SHA256 بدنه.</p></div><div class="rxp-card"><table class="rxp-table"><tr><th>نام</th><th>Prefix</th><th>دسترسی</th><th>انقضا</th><th>وضعیت</th><th></th></tr><?php foreach($keys as$k):?><tr><td><?=rxp_h($k['name'])?></td><td><code><?=rxp_h($k['key_prefix'])?>…</code></td><td><?=rxp_h(implode(',',json_decode($k['permissions'],true)?:[]))?></td><td><?=date('Y/m/d',(int)$k['expires_at'])?></td><td><?=$k['revoked_at']?'لغوشده':((int)$k['expires_at']<time()?'منقضی':'فعال')?></td><td><?php if(!$k['revoked_at']&&(int)$k['expires_at']>=time()):?><form method="post"><input type="hidden" name="action" value="revoke"><input type="hidden" name="id" value="<?=$k['id']?>"><button class="rxp-btn red">لغو</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php rxp_layout_end();
